$.mockjax({
    url: "./login.do",
    type: "post",
    dataType: "json",
    response: function(settings) {

        var req = JSON.parse(settings.data);

        if (req.userId === "crash") {
            this.status = 500;
        } else if (req.userId === "lock") {
            this.status = 423;
        } else {
            var usr = users.find(function (u) {
                return (req.userId === u.userId && req.password === u.password);
            });
            if (!usr) {
                usr = users.find(function (u) {
                    return (req.userId === u.mailAddress && req.password === u.password);
                });
            }
            if (usr) {
                const vdr = vendors.find(function(v) {
                     return usr.vendorId === v.id;
                });

                this.responseText = {
                    vendorId: usr.vendorId,
                    parentId: usr.parentId,
                    vendorName: (vdr)? vdr.name : "",
                    userId: usr.userId,
                    userName: usr.userName,
                    userType: (usr.vendorId === '0000')? '0' : ((usr.admin)? '1' : '2')
                }
            } else {
                this.status = 401;
            }
        }
        console.log("Reqest -> ", req);
        console.log("Response -> ", this.status, this.responseText);

        // ローカルストレージに保存しておく
        try {
            localStorage.clear();
            localStorage.setItem("UVO", JSON.stringify(
                {
                    vendorId: this.responseText.vendorId,
                    parentId: this.responseText.vendorId,
                    vendorName: this.responseText.vendorName,
                    userId: this.responseText.userId,
                    userName: this.responseText.userName,
                    userType: this.responseText.userType
                }
            ));
        } catch (e) {

        }
    }
});

