// @@@@@@@@@@@@@@ ユーザ管理
//----------------------------------------------------------------------------
// 一覧
$.mockjax({
    url: "./sc13_list.do",
    type: "post",
    status: 200,
    responseTime: 500,
    dataType: "json",
    response: function(settings) {

        var req = JSON.parse(settings.data);

        const start = req.offset;
        let end = start + req.limit;

        let isContinue = true;

        users.sort(function(a, b) {
            if (req.sortItem === 'start') {
                if (req.sortOrder === 'desc') {
                    if (a.start < b.start) {
                        return 1;
                    }
                    if (a.start > b.start) {
                        return -1;
                    }
                } else {
                    if (a.start < b.start) {
                        return -1;
                    }
                    if (a.start > b.start) {
                        return 1;
                    }
                }
            }
            return 0;
        });

        var filteredList = [];
        if (global.uvo.userType() === "0") {
            filteredList = users;
        }
        else if (global.uvo.vendorId() === global.uvo.parentId()) {
            filteredList = users.filter(function(user) {
                return (user.parentId === global.uvo.vendorId());
            });
        } else {
            filteredList = users.filter(function(user) {
                return (user.vendorId === global.uvo.vendorId());
            });
        }

        const filteredUsers = filteredList.filter(function(user) {
            if (req.vendorId && req.vendorId !== "") {
                return user.vendorId === req.vendorId;
            }
            return true;
        }).filter(function(user) {
            if (req.userId && req.userId !== "") {
                return user.userId.indexOf(req.userId) >= 0;
            }
            return true;
        }).filter(function(user) {
            if (req.userName && req.userName !== "") {
                return user.userName.indexOf(req.userName) >= 0;
            }
            return true;
        });

        filteredUsers.forEach(function(user) {
            user.key = user._key;
            let vendor = vendors.find(function(v) {
                return v.id === user.vendorId;
            });
            user.vendorName = (vendor)? vendor.name : 'undefine';
        });

        if (end > filteredUsers.length) {
            end = filteredUsers.length;
            isContinue = false;
        }

        filteredUsers.sort(compareValues('vendorId', 'asc'));

        this.responseText = {
            vendors: vendors,
            users: filteredUsers.slice(start, end),
            continue: isContinue
        };
        console.log("Reqest -> ", settings.data);
        console.log("Response -> ", this.status, this.responseText);
    }
});

